number.script:
          function checkRaceLimits()
            -- use the data section to find the maxlevel value
            local sDBnode = window.getDatabaseNode();
            local nodeData = DB.getChild(sDBnode, "data");
            local nMaxLevel = DB.getValue(nodeData, "maxlevel", 20);
            local nMinLevel = DB.getValue(nodeData, "minlevel", 1);
            local nLevel = getValue() or 1;
            if sf.isGt(nMinLevel, nLevel) then
              nLevel = nMinLevel;
              sf.sendChat("Level cannot be set below " .. nMinLevel .. " for this companion.");
            elseif sf.isGt(nLevel, nMaxLevel) then
              nLevel = nMaxLevel;
              sf.sendChat("Level cannot be set above " .. nMaxLevel .. " for this companion.");
            end
            return nLevel;
          end
          function onInit()
            local sDBnode = window.getDatabaseNode();
            local nLevel = DB.getValue(sDBnode,"level",1);

            -- use DB value as source of truth (checks if its between 1 and 20)
            nLevel = CompanionData.validateLevel(nLevel);
            nLevel = checkRaceLimits();
            setValue(nLevel);

            -- since the stat buttons cant have their onInit override
            checkDataStats();
            checkDataSaves();
            checkDataSize();
          end
          function onValueChanged()
            local nLevel = CompanionData.validateLevel(getValue());
            DB.setValue(window.getDatabaseNode(),"level","number",nLevel);

            updateCosts();
            window.attackbonus_base.updateBAB();
            window.nEAC.update();
            window.nKAC.update();
            window.nSkillBonus.update();

            if window.cr then 
              local nLevel = getValue();
              window.cr.setValue(nLevel);
            end
          end
          function updateCosts()
            local sDBnode = window.getDatabaseNode();
            local nLevel = getValue() or 1;

            -- in case the level or HP were not set yet
            DB.setValue(sDBnode,"level","number",nLevel);
            local nHP = CompanionData.getLevelHP(nLevel);

            -- set the window so it can update the DB node
            window.current_maxHP.setValue(nHP);

            local nCost = CompanionData.getLevelCost(nLevel);
            window.cost_current.setValue(nCost);

            local nUpgradeCost = CompanionData.getLevelCost(nLevel + 1);
            window.cost_upgrade.setValue(nUpgradeCost);

            -- Update combat stats when level changes
            window.nEAC.update();
            window.nKAC.update();
            window.nSkillBonus.update();
          end
          function checkDataStats()
            local sDBnode = window.getDatabaseNode();
            local nodeData = DB.getChild(sDBnode, "data");
            local sPrimary = DB.getValue(nodeData, "stat1", "");
            local sSecondary = DB.getValue(nodeData, "stat2", "");

            if sPrimary ~= "" then
              DB.setValue(sDBnode, "stat_primary", "string", sPrimary);
              Debug.console("Initialized Primary Stat cycler to: " .. sPrimary);
            else
              Debug.console("No Primary Stat set in DB, leaving cycler blank.");
            end

            if sSecondary ~= "" then
              DB.setValue(sDBnode, "stat_secondary", "string", sSecondary);
              Debug.console("Initialized Secondary Stat cycler to: " .. sSecondary);
            else
              Debug.console("No Secondary Stat set in DB, leaving cycler blank.");
            end
          end
          function checkDataSaves()
            local sDBnode = window.getDatabaseNode();
            local nodeData = DB.getChild(sDBnode, "saves");
            local sFort = DB.getValue(nodeData, "fortitude.type", "Poor");
            local sRef = DB.getValue(nodeData, "reflex.type", "Poor");
            local sWill = DB.getValue(nodeData, "will.type", "Poor");

            if sFort ~= "" then
              DB.setValue(sDBnode, "save_fort", "string", sFort);
              Debug.console("Initialized Fortitude Save to: " .. sFort);
            else
              Debug.console("No Fortitude Save set in DB, leaving cycler blank.");
            end

            if sRef ~= "" then
              DB.setValue(sDBnode, "save_reflex", "string", sRef);
              Debug.console("Initialized Reflex Save to: " .. sRef);
            else
              Debug.console("No Reflex Save set in DB, leaving cycler blank.");
            end

            if sWill ~= "" then
              DB.setValue(sDBnode, "save_will", "string", sWill);
              Debug.console("Initialized Will Save to: " .. sWill);
            else
              Debug.console("No Will Save set in DB, leaving cycler blank.");
            end
          end
          function checkDataSize()
            local sDBnode = window.getDatabaseNode();
            local sSize = DB.getValue(sDBnode, "size", "Medium"); --sSize is the name of the associated size button cycler control
            if sSize ~= "" then
              DB.setValue(sDBnode, "sSize", "string", sSize);
              Debug.console("Initialized Size cycler to: " .. sSize);
            else
              Debug.console("No Size set in DB, leaving cycler blank.");
            end
          end

