buttoncontrol.script:
          function onButtonPress()
            sf.DebugOut("Committing ability score changes...");
            
            local sDBnode = window.getDatabaseNode();
            local nLevel = window.current_level.getValue() or 1;
            local sPrimaryStat = window.stat_primary.getStringValue();
            local sSecondaryStat = window.stat_secondary.getStringValue();
            
            -- Validate that primary and secondary are different
            if sPrimaryStat == sSecondaryStat then
              sf.ErrorOut("Primary and Secondary stats must be different!");
              return;
            end
            
            -- List of all ability scores
            local abilities = {"charisma", "constitution", "dexterity", "intelligence", "strength", "wisdom"};
            
            -- Step 1: Reset all ability scores to defaults
            -- All scores start at 10 (+0 bonus) except Intelligence which is 2 (-4 bonus)
            for _, ability in ipairs(abilities) do
              local nodeAbility = DB.getChild(sDBnode, "abilities." .. ability);
              local defaultScore = (ability == "intelligence") and 2 or 10;
              local defaultBonus = CompanionData.getStatBonus(defaultScore);
              
              DB.setValue(nodeAbility, "base", "number", defaultScore);
              DB.setValue(nodeAbility, "score", "number", defaultScore);
              DB.setValue(nodeAbility, "bonus", "number", defaultBonus);
              
              sf.DebugOut("Reset " .. ability .. " to score " .. defaultScore .. " (bonus " .. defaultBonus .. ")");
            end
            
            -- Step 2: Apply primary stat bonus
            if sPrimaryStat ~= "" then
              local nPrimaryBonus = CompanionData.getLevelFirstAbility(nLevel);
              local nPrimaryScore = CompanionData.getScoreFromBonus(nPrimaryBonus);
              
              local nodePrimary = DB.getChild(sDBnode, "abilities." .. sPrimaryStat);
              DB.setValue(nodePrimary, "base", "number", nPrimaryScore);
              DB.setValue(nodePrimary, "score", "number", nPrimaryScore);
              DB.setValue(nodePrimary, "bonus", "number", nPrimaryBonus);
              
              sf.DebugOut("Set Primary Stat " .. sPrimaryStat .. " to score " .. nPrimaryScore .. " (bonus " .. nPrimaryBonus .. ")");
            end
            
            -- Step 3: Apply secondary stat bonus
            if sSecondaryStat ~= "" then
              local nSecondaryBonus = CompanionData.getLevelSecondAbility(nLevel);
              local nSecondaryScore = CompanionData.getScoreFromBonus(nSecondaryBonus);
              
              local nodeSecondary = DB.getChild(sDBnode, "abilities." .. sSecondaryStat);
              DB.setValue(nodeSecondary, "base", "number", nSecondaryScore);
              DB.setValue(nodeSecondary, "score", "number", nSecondaryScore);
              DB.setValue(nodeSecondary, "bonus", "number", nSecondaryBonus);
              
              sf.DebugOut("Set Secondary Stat " .. sSecondaryStat .. " to score " .. nSecondaryScore .. " (bonus " .. nSecondaryBonus .. ")");
            end

            -- Update initiative from Dexterity bonus
            local nodeDex = DB.getChild(sDBnode, "abilities.dexterity");
            local nDexBonus = DB.getValue(nodeDex, "bonus", 0);
            local nodeInitiative = DB.getChild(sDBnode, "initiative");
            if nodeInitiative then
              DB.setValue(nodeInitiative, "abilitymod", "number", nDexBonus);
              local nMisc = DB.getValue(nodeInitiative, "misc", 0);
              local nTemp = DB.getValue(nodeInitiative, "temporary", 0);
              DB.setValue(nodeInitiative, "total", "number", nDexBonus + nMisc + nTemp);
            end
            if window.nInitiative then
              window.nInitiative.update();
            end
            
            sf.DebugOut("Ability score commit complete!");
          end

button_stringcycler.script:
        function onValueChanged()
          local sSaveType = getStringValue();
          local nSaveBonus = 0;
          local nLevel = window.current_level.getValue() or 1;          
          sf.DebugOut("Fortitude Save Type selected: " .. sSaveType);

          -- get the good or base save from reference data then write to DB
          if sSaveType == "" then
            sf.DebugOut("No save type selected, skipping.");
            return;
          elseif sSaveType == "Good" or sSaveType == "good"  then
            nSaveBonus = CompanionData.getLevelGoodSave(nLevel);
          elseif sSaveType == "Poor" or sSaveType == "poor" then
            nSaveBonus = CompanionData.getLevelPoorSave(nLevel);
          end

          -- DB save to saves.fortitude.base
          local sDBnode = window.getDatabaseNode();
          DB.setValue(sDBnode,"saves.fortitude.base","number",nSaveBonus);
        end

