stringcontrol.script:
          function initSizeCycler()
            if not window or not window.sSize then
              return;
            end

            if onSizeCyclerInit then
              onSizeCyclerInit(window, window.sSize);
            end
          end

          function handleSizeCyclerChanged(control)
            if onSizeCyclerChanged then
              onSizeCyclerChanged(window, control);
            else
              sf.DebugOut("No onSizeCyclerChanged handler defined.");
            end
          end

          function onInit()
            initSizeCycler();
          end

button_stringcycler.script:
          function onValueChanged()
            sf.DebugOut("Creature Size selected: " .. getStringValue());

