buttoncontrol.script:
function onButtonPress()
  sf.DebugOut("Applying skill bonuses...");
  
  local sDBnode = window.getDatabaseNode();
  local nSkillBonus = window.nSkillBonus.getValue() or 0;
  local sSkillList = window.sSkillList.getValue() or "";
  
  if sSkillList == "" then
    sf.ErrorOut("No skills specified!");
    return;
  end
  
  local skills = {};
  for skillName in string.gmatch(sSkillList, "([^,]+)") do
    skillName = skillName:match("^%s*(.-)%s*$");
    if skillName ~= "" then
      local skillEntry = skillName .. " +" .. tostring(nSkillBonus);
      table.insert(skills, skillEntry);
    end
  end
  
  local sFormattedSkills = table.concat(skills, ", ");
  DB.setValue(sDBnode, "skills", "string", sFormattedSkills);
  
  sf.DebugOut("Skills updated: " .. sFormattedSkills);
end

button_details.script:
         function onInit()
            -- on init, check if the companion wizard helper is enabled; if not, hide the button
            if not sf_init.isCompanionWizard_On() then
              setVisible(false);
            else
              setVisible(true);
            end
          end
					function onButtonPress()
            local sDBnode = window.getDatabaseNode();
            sf.DebugOut("DB Node: " .. sDBnode.getPath());

            if not sf_init.isCompanionWizard_On() then
              sf.ErrorOut("Creature Companion Wizard is disabled; not opening ability boost details.");
              return;
            end

            -- check if the companion record has a data section which confirms it has a valid race applied; if not, show error and don't open the defaults window
            if not DB.getChild(sDBnode, "data") then
              local sCompanionName = DB.getValue(sDBnode, "name", "Unknown Companion");
              sf.sendChat("Companion [" .. sCompanionName .. "] has no valid race applied; please assign a race before continuing.");
              return;
            end

            Interface.openWindow("companionSetDefaults", sDBnode);
					end
